<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, mutation } from '../api/client'
import { followRun } from '../api/runEvents'
import ContextTrace from './ContextTrace.vue'
import { type StudyTrack, type StudyPlan, type StudyModule, type Block, activeStates } from '../types/study'
const props=defineProps<{track:StudyTrack;plan:StudyPlan;module:StudyModule;embedded?:boolean;reading?:{view_intent:string;step_index:number;repository_snapshot_id?:string;path?:string;start_line?:number;end_line?:number;citation_id?:string}}>()
const emit=defineEmits<{changed:[];open:[id:string];point:[value:{citation_id:string;quote_start_line:number;quote_end_line:number}]}>()
const write=mutation(),question=ref(''),busy=ref(false),follow=ref(true),calls=ref(3),cap=ref(4096),events=ref<string[]>([])
const turns=computed(()=>props.track.turns.filter(t=>t.plan_id===props.plan.id&&t.module_key===props.module.key))
const active=computed(()=>!!props.track.active_run&&activeStates.includes(props.track.active_run.status))
let controller:AbortController|undefined,followed='',observedRun=''
watch(()=>props.track.active_run?.run_id, id=>{
 if(!id||id===observedRun||!active.value)return
 observedRun=id;controller?.abort();controller=new AbortController();events.value=[]
 void followRun(id,event=>{
  const labels:Record<string,string>={'run.started':'Agent 开始读取上下文','stage.completed':'阶段结果已保存','study.context':'上下文与证据指针已保存','study.tool':'已执行只读代码工具','run.finished':'本轮已结束','run.cancelled':'已停止','stage.failed':'结果未通过校验'}
  if(labels[event.type])events.value.push(labels[event.type]+(event.type==='study.tool'?' · '+String(event.payload?.name??''):''))
  emit('changed')
 },()=>{},controller.signal)
},{immediate:true})
watch(()=>turns.value.at(-1)?.id, id=>{
 const turn=turns.value.at(-1)
 if(id&&id!==followed){followed=id;if(follow.value&&turn?.focus_citation_id){const point=turn.points.find(p=>p.citation_id===turn.focus_citation_id);if(point)emit('point',point)}}
},{immediate:true})
onBeforeUnmount(()=>controller?.abort())
async function send(){
 if(busy.value||active.value||!question.value.trim())return
 if(props.track.independent_attempt_active){ElMessage.warning('独立尝试进行中，请先提交或结束尝试');return}
 try{await ElMessageBox.confirm(`本轮最多 ${calls.value} 次模型调用，每次最多 ${cap.value} 输出 token，只读当前模块的审核项目。按供应商用量计费。`,'发送给指导 Agent',{confirmButtonText:'发送本轮问题',cancelButtonText:'取消'})
 busy.value=true
 await write('/study/tracks/'+props.track.track_id+'/runs','POST',{expected_revision:props.track.revision,role:'tutor',reading:props.reading,plan_id:props.plan.id,module_key:props.module.key,question:question.value,max_output_tokens:cap.value,model_call_limit:calls.value})
 question.value='';emit('changed')
 }catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}finally{busy.value=false}
}
async function stop(){const run=props.track.active_run;if(!run)return;try{await api('/runs/'+run.run_id+'/cancel','POST',{expected_version:run.version});emit('changed')}catch(e){ElMessage.error(String(e))}}
function pos(block:Block,key:string){const i=block.nodes.findIndex(n=>n.key===key);return {x: i%2*350+35,y:Math.floor(i/2)*100+20}}
</script>
<template><div class="study-tutor" :class="{embedded}"><header v-if="!embedded"><h2>指导学习 Agent</h2><el-switch v-model="follow" active-text="跟随代码定位"/></header><p v-if="!embedded" class="muted">当前模块：{{module.title}}<br>可随时提问；只读取此模块对应的审核项目。</p>
<el-alert v-if="track.independent_attempt_active" title="独立尝试进行中：导师问答暂时停用。历史解释仍可查看；提交或结束尝试后恢复。" type="warning" :closable="false"/><div class="turns"><article v-for="t in turns" :key="t.id" class="turn"><p class="question">{{t.question}}</p><el-tag v-if="t.synthetic" type="warning" size="small">离线模拟</el-tag><el-tag v-if="t.status==='insufficient_evidence'" type="info" size="small">依据不足</el-tag>
<section v-for="(b,i) in t.blocks" :key="i" class="block"><h4 v-if="b.title">{{b.title}}</h4><p v-if="b.kind==='text'" class="text">{{b.text}}</p>
<svg v-else-if="b.kind==='diagram'" :viewBox="'0 0 720 '+Math.ceil(b.nodes.length/2)*100" role="img" :aria-label="b.title||'Agent 学习图示'"><g v-for="(e,j) in b.edges" :key="'e'+j"><line :x1="pos(b,e.source).x+140" :y1="pos(b,e.source).y+32" :x2="pos(b,e.target).x+140" :y2="pos(b,e.target).y+32" stroke="#bab3db" stroke-width="2"/><text :x="(pos(b,e.source).x+pos(b,e.target).x)/2+140" :y="(pos(b,e.source).y+pos(b,e.target).y)/2+25" text-anchor="middle" font-size="12" fill="#7565a1">{{e.label}}</text></g><g v-for="n in b.nodes" :key="n.key"><rect :x="pos(b,n.key).x" :y="pos(b,n.key).y" width="280" height="64" rx="10" fill="#efedff" stroke="#c5baf2"/><text :x="pos(b,n.key).x+140" :y="pos(b,n.key).y+37" text-anchor="middle" font-size="15" fill="#6252b5">{{n.label.length>19?n.label.slice(0,19)+'…':n.label}}</text><title>{{n.label}}</title></g></svg>
<div v-else-if="b.kind==='table'" class="table-scroll"><table><thead><tr><th v-for="(c,j) in b.columns" :key="j">{{c}}</th></tr></thead><tbody><tr v-for="(r,j) in b.rows" :key="j"><td v-for="(cell,k) in r" :key="k">{{cell}}</td></tr></tbody></table></div></section>
<article v-for="p in t.points" :key="p.citation_id+p.title" class="code-point"><strong>{{p.title}}</strong><p>{{p.explanation}}</p><small>引用定位已校验 · 语义支持未独立核验 · 无运行观察</small><pre>{{p.quote}}</pre><el-button link @click="emit('point',p)">{{p.path}}:{{p.quote_start_line}}–{{p.quote_end_line}} · 查看引用位置</el-button></article>
<ContextTrace v-if="t.context_run_id" :track-id="track.track_id" :run-id="t.context_run_id" @open="id=>emit('open',id)"/><details v-if="t.limitations.length"><summary>范围与未知</summary><p v-for="l in t.limitations" :key="l" class="muted">{{l}}</p></details><div v-if="t.questions.length"><small>接下来可以问</small><el-button v-for="q in t.questions" :key="q" link @click="question=q">{{q}}</el-button></div></article>
<div v-if="!turns.length" class="tutor-welcome"><span>✦</span><strong>从当前实现开始理解</strong><p>询问代码、设计取舍或下一步学习顺序。回答会保留实际代码引用；你发送问题后才调用模型。</p></div></div>
<div class="tutor-bottom"><details v-if="active||events.length" class="tutor-progress"><summary>{{active?'Agent 正在读取与整理依据':'本轮任务进度'}}</summary><ContextTrace v-if="track.active_run?.role==='tutor'&&active" :key="track.active_run.run_id" :track-id="track.track_id" :run-id="track.active_run.run_id" @open="id=>emit('open',id)"/><ol><li v-for="(e,i) in events.slice(-5)" :key="i">{{e}}</li></ol><el-button v-if="active" link @click="stop">停止本轮</el-button></details><div class="tutor-context"><strong>当前阶段 · 源码学习</strong><span>{{module.title}}</span></div><div class="tutor-suggestions"><button @click="question='请结合原文解释当前模块的核心代码与边界。'">解释当前代码</button><button @click="question='如何围绕这个模块完成当前学习目标？'">如何完成学习方式？</button><button @click="question='基于当前模块与前置关系，下一步应该学习什么？'">下一步怎么学？</button></div><div class="tutor-composer"><el-input v-model="question" type="textarea" :rows="2" placeholder="询问当前学习目标或代码实现…" @keydown.enter.exact.prevent="send"/><button class="tutor-send" :disabled="busy||track.independent_attempt_active||active||!question.trim()" :aria-label="busy?'正在发送':'发送学习问题'" @click="send">{{busy||active?'…':'➤'}}</button></div><details class="tutor-budget"><summary>模型预算与跟随定位</summary><p>gpt-6.1-sol · low</p><label>最多调用 <el-input-number v-model="calls" :min="1" :max="3" size="small"/></label><label>每次输出 <el-input-number v-model="cap" :min="512" :max="8192" :step="512" size="small"/></label><el-switch v-model="follow" active-text="跟随已校验代码引用"/></details><div class="tutor-meta"><span>学习会话 · 当前模块</span><span>Enter 发送 · Shift+Enter 换行</span></div></div></div></template>
<style scoped>
.study-tutor{font-size:12px;color:#63708b;display:flex;flex-direction:column;min-height:0;overflow:hidden}.study-tutor.embedded{flex:1}.study-tutor>header{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 14px}.study-tutor h2{font-size:14px;margin:0}.study-tutor>p{margin:0 14px 10px}.muted,small{font-size:10px;color:#98a4b7;line-height:1.8}.turns{flex:1;min-height:0;overflow:auto;padding:15px 16px}.turn{font-size:12px;padding-bottom:14px;margin-bottom:16px;overflow-wrap:anywhere}.question{padding:10px 12px;margin:4px 0 16px 25px;background:#f0edff;border-radius:11px 3px 11px 11px;color:#7968bd;white-space:pre-wrap;line-height:1.8}.text,.code-point p{line-height:1.9;white-space:pre-wrap}.block{background:#f7f8fc;border:1px solid #edf0f7;border-radius:2px 11px 11px 11px;padding:10px 12px;margin-bottom:10px}.block h4{margin:0 0 8px;color:#526077;font-size:12px}.block p{margin:2px 0}.block svg{width:100%;min-height:130px;background:#faf9ff;border-radius:8px}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:10px}th,td{border:1px solid #e6eaf2;padding:7px;text-align:left}th{background:#f0edff;color:#8170be}.code-point{margin:12px 0;padding:12px;background:#f8f9fc;border:1px solid #e6eaf2;border-radius:9px}.code-point>strong{font-size:11px;color:#63708b}.code-point pre{white-space:pre-wrap;font:11px/1.8 Consolas,monospace;overflow:auto;max-height:180px;background:#111c2e;color:#c7d7e9;border-radius:6px;padding:10px}.code-point .el-button,.turn .el-button{white-space:normal;line-height:1.7;height:auto;text-align:left;font-size:10px}.turn small{display:block}.turn>div>.el-button{display:block;margin-left:0}.turn details{margin:10px 0}.turn summary{font-size:10px;cursor:pointer;color:#98a4b7}.tutor-welcome{margin:10px 2px 20px;padding:15px;background:#fafbfe;border:1px solid #edf0f7;border-radius:12px;line-height:1.9;color:#98a4b7;font-size:11px}.tutor-welcome>span{display:grid;place-items:center;width:25px;height:25px;color:#7665ed;background:#efedff;border-radius:7px;font-size:17px;margin-bottom:10px}.tutor-welcome>strong{font-size:12px;font-weight:550;color:#63708b}.tutor-welcome>p{margin:6px 0}.tutor-bottom{flex:none;padding:12px 14px 13px;border-top:1px solid #e6eaf2;background:#fff}.tutor-context{border:1px solid #e6e0ff;border-radius:9px;background:#f8f6ff;padding:9px 11px;display:grid;gap:5px;font-size:10px;margin-bottom:10px}.tutor-context strong{font-size:10px;font-weight:600;color:#7665ed}.tutor-context>span{color:#98a4b7;line-height:1.6}.tutor-suggestions{display:flex;gap:5px;margin:9px 0;flex-wrap:wrap}.tutor-suggestions button{font-size:10px;color:#8779db;background:#fff;border:1px solid #e5e0fa;border-radius:7px;padding:7px 8px;white-space:nowrap}.tutor-composer{position:relative;border:1px solid #dce3f0;border-radius:12px;background:#fff;min-height:66px}.tutor-composer :deep(.el-textarea__inner){box-shadow:none!important;border:0;resize:none;min-height:64px!important;padding:10px 42px 12px 10px;font-size:11px;color:#526077;background:transparent;line-height:1.7}.tutor-composer :deep(.el-textarea__inner::placeholder){color:#a5b0c3}.tutor-send{position:absolute;right:8px;bottom:8px;width:32px;height:32px;display:grid;place-items:center;border:0;border-radius:9px;background:#6658e5;color:#fff;font-size:17px}.tutor-send:disabled{background:#c8c2ec}.tutor-budget,.tutor-progress{font-size:10px;color:#98a4b7;margin:7px 0}.tutor-budget summary,.tutor-progress summary{cursor:pointer}.tutor-budget p{margin:8px 0}.tutor-budget label{display:flex;align-items:center;gap:8px;font-size:10px;margin:7px 0}.tutor-meta{font-size:8px;color:#a4afc2;display:flex;justify-content:space-between;gap:5px;margin-top:7px}.tutor-progress{max-height:180px;overflow:auto}.study-tutor>.el-alert{flex:none;margin:8px;width:auto}
</style>
